<script setup>
import {ref,reactive,watch,computed,onBeforeUnmount} from 'vue';import {api,session,errorText} from '../services/api.js';
const props=defineProps({propertyId:{type:String,required:true},ownerId:[Number,String]});
const own=computed(()=>String(props.ownerId)===String(session.user?.id)),admin=computed(()=>session.user?.role==='ADMIN');
const rows=ref([]),busy=ref(false),error=ref(''),notice=ref(''),selected=ref(null),file=ref(null),reason=ref('');let sequence=0;
const blank=()=>({documentType:'OTHER',ownerName:'',documentNumber:'',issueDate:''}),form=reactive(blank());
async function load(){const run=++sequence;busy.value=true;error.value='';rows.value=[];try{const r=await api('/properties/'+props.propertyId+'/legal-documents?page=0&size=20');if(run===sequence)rows.value=r.items||[]}catch(e){if(run===sequence)error.value=errorText(e)}finally{if(run===sequence)busy.value=false}}
onBeforeUnmount(()=>sequence++);
watch(()=>[props.propertyId,session.user?.id],()=>{selected.value=null;file.value=null;Object.assign(form,blank());load()},{immediate:true});
function edit(doc){selected.value=doc;Object.assign(form,{documentType:doc.documentType,ownerName:doc.ownerName,documentNumber:doc.documentNumber||'',issueDate:doc.issueDate||''});notice.value='Sửa metadata sẽ yêu cầu duyệt lại.'}
function choose(e){file.value=e.target.files?.[0]||null;e.target.value='';if(file.value&&(!['image/jpeg','image/png','application/pdf'].includes(file.value.type)||file.value.size>10*1024*1024)){file.value=null;error.value='Chỉ JPEG/PNG/PDF, tối đa 10 MiB mỗi tệp.'}}
async function run(fn){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn();await load()}catch(e){error.value=e.status===409?'Hồ sơ đã thay đổi hoặc vượt quota. Hãy tải lại trước khi thao tác.':errorText(e)}finally{busy.value=false}}
async function save(){if(!own.value)return;await run(async()=>{const metadata={documentType:form.documentType,ownerName:form.ownerName.trim(),documentNumber:form.documentNumber.trim()||null,issueDate:form.issueDate||null},base='/properties/'+props.propertyId+'/legal-documents';if(selected.value)await api(base+'/'+selected.value.id+'?expectedVersion='+selected.value.contentVersion,{method:'PATCH',body:metadata});else{if(!file.value)throw Error('Hãy chọn tệp bằng chứng.');const data=new FormData();data.append('metadata',new Blob([JSON.stringify(metadata)],{type:'application/json'}),'metadata.json');data.append('file',file.value);await api(base,{method:'POST',body:data})}selected.value=null;file.value=null;Object.assign(form,blank());notice.value='Hồ sơ đã lưu trên server và đang chờ duyệt.'})}
async function remove(doc){if(!confirm('Xóa mềm hồ sơ này?'))return;await run(()=>api('/properties/'+props.propertyId+'/legal-documents/'+doc.id+'?expectedVersion='+doc.contentVersion,{method:'DELETE'}))}
async function download(doc){await run(async()=>{const blob=await api('/properties/'+props.propertyId+'/legal-documents/'+doc.id+'/content',{responseType:'blob'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='legal-document.'+(doc.mimeType==='application/pdf'?'pdf':doc.mimeType==='image/png'?'png':'jpg');a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)})}
async function review(doc,status){if(!reason.value.trim()){error.value='Cần lý do duyệt/từ chối.';return}await run(()=>api('/admin/legal-documents/'+doc.id+'/review',{method:'POST',body:{status,reason:reason.value.trim(),expectedVersion:doc.contentVersion}}))}
</script><template><section class="rounded-[22px] bg-white p-6" aria-label="Hồ sơ pháp lý trên server"><h2 class="text-lg font-semibold">Hồ sơ pháp lý</h2><p class="my-3 text-xs">Tệp riêng tư chỉ chủ tin và quản trị viên được xem. Hồ sơ chỉ được lưu khi server xác nhận; tối đa 10 tệp, JPEG/PNG/PDF ≤10 MiB. Sửa thông tin sẽ đưa hồ sơ về chờ duyệt.</p><p v-if="error" role="alert" class="my-3 text-sm text-red-800">{{error}} <button :disabled="busy" @click="load" class="underline">Tải lại</button></p><p v-if="busy" role="status">Đang xử lý hồ sơ…</p><p v-if="notice" role="status">{{notice}}</p><p v-if="!busy&&!error&&!rows.length">Chưa có hồ sơ pháp lý trên server.</p>
<ul><li v-for="doc in rows" :key="doc.id" class="my-4 rounded-xl border p-4 text-sm"><p>{{doc.documentType}} · {{doc.status}} · phiên bản {{doc.contentVersion}}</p><p>{{doc.ownerName}} · {{doc.documentNumber||'Chưa có số giấy'}} · {{doc.issueDate||'Chưa có ngày cấp'}}</p><p v-if="doc.reviewReason">Kết quả: {{doc.reviewReason}}</p><button :disabled="busy" @click="download(doc)" class="completion-button">Tải tệp riêng</button><template v-if="own"><button :disabled="busy" @click="edit(doc)" class="completion-button">Sửa thông tin</button><button :disabled="busy" @click="remove(doc)" class="completion-button">Xóa hồ sơ</button></template><template v-if="admin&&!own"><button :disabled="busy" @click="review(doc,'VERIFIED')" class="completion-button">Xác minh</button><button :disabled="busy" @click="review(doc,'REJECTED')" class="completion-button">Từ chối</button></template></li></ul>
<label v-if="admin&&!own" class="block text-sm">Lý do kiểm duyệt <textarea v-model="reason" maxlength="4000" class="completion-input w-full"/></label><p v-if="admin&&own" class="text-xs">Không được tự duyệt giấy tờ của mình.</p>
<form v-if="own" @submit.prevent="save" class="space-y-3"><h3 class="font-semibold">{{selected?'Chỉnh sửa hồ sơ':'Thêm hồ sơ riêng tư'}}</h3><label class="block text-sm">Loại giấy tờ <select v-model="form.documentType" class="completion-input"><option value="LAND_USE_RIGHT">Quyền sử dụng đất</option><option value="HOME_OWNERSHIP">Sở hữu nhà</option><option value="SALE_CONTRACT">Hợp đồng mua bán</option><option value="OTHER">Khác</option></select></label><label class="block text-sm">Chủ sở hữu trên giấy tờ <input v-model="form.ownerName" required maxlength="150" class="completion-input"/></label><label class="block text-sm">Số giấy <input v-model="form.documentNumber" maxlength="150" class="completion-input"/></label><label class="block text-sm">Ngày cấp <input v-model="form.issueDate" type="date" :max="new Date().toISOString().slice(0,10)" class="completion-input"/></label><label v-if="!selected" class="block text-sm">Tệp riêng tư <input type="file" accept="image/jpeg,image/png,application/pdf" @change="choose" class="completion-input"/>{{file?.name}}</label><button :disabled="busy||(!selected&&rows.length>=10)" class="completion-button">{{selected?'Lưu metadata':'Tải và lưu hồ sơ'}}</button><button v-if="selected" type="button" class="completion-button" @click="selected=null;Object.assign(form,blank())">Hủy chỉnh sửa</button></form></section></template>

<style scoped>.completion-button{padding:8px 14px;margin:6px;border:1px solid #142b4f;border-radius:20px;background:#142b4f;color:white;font-size:12px}.completion-button:disabled{opacity:.5}.completion-input{padding:10px;border:1px solid #d6dce3;border-radius:8px;max-width:100%}:focus-visible{outline:3px solid #b49362;outline-offset:3px}</style>
